const a  = $input.first().json;
const tr = $('When chat message received').first().json;
const t0 = Number($('Mark t0').first().json.t0);

const steps = a.intermediateSteps ?? [];

const toolCalls = steps.map(s => ({
  tool:  s.action?.tool ?? null,
  input: s.action?.toolInput ?? null,
}));

// The model's harmony framing leaks into the answer roughly one turn in eleven —
// a stored answer starting 'thought<channel|>' is what a later mem reader would
// take for the assistant's own words. Strip it on the way to STORAGE only; never
// strip the model's output path, which would hide the leak instead of fixing it.
function stripChannel(s) {
  return String(s ?? '')
    .replace(/<\|?\/?(?:channel|start|end|message|final|analysis)\|?>/gi, '')
    .replace(/^\s*thought\s*/i, '')
    .trim();
}

return [{ json: {
  session_id: String(tr.sessionId ?? 'unknown'),
  user_text:  String(tr.chatInput ?? ''),
  content:    stripChannel(a.output),
  tool_calls: JSON.stringify(toolCalls),
  // chunk_ids are NOT recovered here any more. The tool hands the model
  // mode 'text', which carries no chunk_id by design, so the regex that used to
  // sit here could never match — 0 of 22 turns. `Log turn` joins obs.retrievals
  // instead, and t0_iso bounds that join to this turn.
  t0_iso:     new Date(t0).toISOString(),
  latency_ms: Date.now() - t0,
  model:      'gemma4:12b',
}}];

// t0 for the turn's latency. This has to live at the trigger: `Prep turn`
// runs after the agent has already answered, so by then the start is gone.
return [{ json: { ...$input.first().json, t0: Date.now() } }];
